-- 1. TAO ROLE UNG DUNG KHONG DUOC PHEP VUOT RLS
CREATE ROLE domation_app NOINHERIT LOGIN PASSWORD 'strong-vault-secret' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;

CREATE TABLE crm_leads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL,
  agency_id uuid NOT NULL,
  full_name text NOT NULL,
  phone_encrypted bytea NOT NULL,
  stage text NOT NULL DEFAULT 'new',
  created_at timestamptz NOT NULL DEFAULT now()
);

-- Bat buoc danh Index tren cot loc RLS de tranh Sequential Scan
CREATE INDEX idx_crm_leads_tenant_agency ON crm_leads (tenant_id, agency_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON crm_leads TO domation_app;

-- 2. CUONG BUC FORCE ROW LEVEL SECURITY (AP DUNG CA VOI TABLE OWNER)
ALTER TABLE crm_leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm_leads FORCE ROW LEVEL SECURITY;

-- Chinh sach co lap tuyet doi; chan 0 dong neu thieu bien ngu canh
CREATE POLICY tenant_agency_isolation ON crm_leads
  FOR ALL
  TO domation_app
  USING (
    tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid
    AND (
      current_setting('app.current_role', true) = 'hq_admin'
      OR agency_id = NULLIF(current_setting('app.current_agency_id', true), '')::uuid
    )
  )
  WITH CHECK (
    tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid
    AND agency_id = NULLIF(current_setting('app.current_agency_id', true), '')::uuid
  );

-- 3. TRONG TRANSACTION PGBOUNCER: LUON DUNG SET LOCAL
BEGIN;
  SELECT set_config('app.current_tenant_id', '9f1c2a10-7b2e-4f19-a8d0-112233445566', true);
  SELECT set_config('app.current_agency_id', '4b88e201-9c12-40d4-9e77-aa11bb22cc33', true);
  SELECT set_config('app.current_role', 'agency_sale', true);
  SELECT id, full_name, stage FROM crm_leads ORDER BY created_at DESC LIMIT 20;
COMMIT;

